values[values == fillvalue$value] &lt;- NA

dates &lt;- as.Date(
  time,
  origin = "1800-01-01"
)

years &lt;- as.integer(
  format(dates, "%Y")
)

netcdf_period &lt;- assign_climate_period(years)

period_levels &lt;- climate_periods$period_abbr

values_period &lt;- simplify2array(
  lapply(
    period_levels,
    function(p) {
      period_index &lt;-
        years &gt;= analysis_start_year &
          years &lt;= analysis_end_year &
          !is.na(netcdf_period) &
          netcdf_period == p

      apply(
        values[
          , ,
          period_index,
          drop = FALSE
        ],
        c(1, 2),
        mean,
        na.rm = TRUE
      )
    }
  )
)

# Grid spacing
lon_resolution &lt;- median(diff(sort(unique(lon))))
lat_resolution &lt;- median(diff(sort(unique(lat))))

# Create one polygon for every netCDF grid cell
grid_geometry &lt;- st_make_grid(
  st_as_sfc(
    st_bbox(
      c(
        xmin = min(lon) - lon_resolution / 2,
        xmax = max(lon) + lon_resolution / 2,
        ymin = min(lat) - lat_resolution / 2,
        ymax = max(lat) + lat_resolution / 2
      ),
      crs = st_crs(4326)
    )
  ),
  cellsize = c(
    lon_resolution,
    lat_resolution
  ),
  what = "polygons"
)

grid_centers &lt;- expand.grid(
  lon = lon,
  lat = lat
)

grid_sf &lt;- st_sf(
  cell_id = seq_len(nrow(grid_centers)),
  grid_centers,
  geometry = grid_geometry,
  crs = 4326
)

df_gridded &lt;- expand.grid(
  cell_id = seq_len(length(lon) * length(lat)),
  climate_period = period_levels
) |&gt;
  mutate(
    avg_anomaly = as.vector(values_period)
  ) |&gt;
  filter(
    is.finite(avg_anomaly)
  ) |&gt;
  mutate(
    climate_period = factor(
      climate_period,
      levels = period_levels,
      ordered = TRUE
    )
  )

sf_gridded &lt;- df_gridded |&gt;
  left_join(
    grid_sf,
    by = "cell_id"
  ) |&gt;
  st_as_sf()

sf_gridded &lt;- sf_gridded |&gt;
  st_transform(mollweide_crs)

sf_gridded &lt;- sf_gridded |&gt;
  mutate(
    area_km2 = as.numeric(
      st_area(geometry)
    ) / 1e6
  )

