df_decade &lt;- df_annual |&gt;
  group_by(
    geographic_id,
    decade
  ) |&gt;
  summarize(
    anomaly = mean(
      anomaly,
      na.rm = TRUE
    ),
    n_years = sum(
      !is.na(anomaly)
    ),
    .groups = "drop"
  )
df_hemisphere_period &lt;- df_monthly |&gt;
  filter(
    geographic_id != "G",
    !is.na(climate_period)
  ) |&gt;
  group_by(
    geographic_id,
    climate_period
  ) |&gt;
  summarize(
    avg_anomaly = mean(anomaly, na.rm = TRUE),
    n_months = sum(!is.na(anomaly)),
    .groups = "drop"
  )
df_zone_period &lt;- df_zonal |&gt;
  filter(!is.na(climate_period)) |&gt;
  group_by(
    zonal_id,
    zone,
    climate_period
  ) |&gt;
  summarize(
    avg_anomaly = mean(anomaly, na.rm = TRUE),
    n_years = sum(!is.na(anomaly)),
    .groups = "drop"
  )

df_hemisphere_period &lt;- df_hemisphere_period |&gt;
  mutate(
    climate_period = factor(
      climate_period,
      levels = climate_period_levels,
      ordered = TRUE
    )
  )
df_zone_period &lt;- df_zone_period |&gt;
  mutate(
    climate_period = factor(
      climate_period,
      levels = climate_period_levels,
      ordered = TRUE
    )
  )
